INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('aurelie-victoire-celanie', 'Aurélie-Victoire Célanie', 'Peinture, dessin et installation', 'Painting, drawing and installation', 'Originaire de Guadeloupe, Aurélie-Victoire Célanie développe une pratique mêlant peinture, dessin et installation. Son travail explore notamment les questions de filiation, de mémoire et de construction identitaire, dans un dialogue constant entre héritages et expérience contemporaine.', 'Originally from Guadeloupe, Aurélie-Victoire Célanie develops a practice combining painting, drawing and installation. Her work explores questions of filiation, memory and identity construction, in a constant dialogue between heritage and contemporary experience.', '/images/artworks/celanie-2.jpg', 'https://g3a.org/g3a-visual-arts-2026-decouvrez-les-six-artistes-selectionnes/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('cruzz-taylor', 'Cruzz Taylor', 'Photographie', 'Photography', 'Photographe et danseur autodidacte, Cruzz Taylor place l''humain, la dignité et la mémoire au centre de son travail. À travers ses images, il cherche notamment à dépasser les représentations réductrices de certains territoires pour restituer la complexité des personnes qui les habitent.', 'A self-taught photographer and dancer, Cruzz Taylor places the human being, dignity and memory at the centre of his work. Through his images, he seeks in particular to move beyond reductive representations of certain territories and to restore the complexity of the people who live there.', '/images/artworks/taylor-1.jpg', 'https://g3a.org/g3a-visual-arts-2026-decouvrez-les-six-artistes-selectionnes/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('nathalie-morere', 'Nathalie Morère', 'Sculpture et céramique', 'Sculpture and ceramics', 'Artiste plasticienne travaillant notamment la sculpture et la céramique, Nathalie Morere développe un univers où se rencontrent mémoire, identité, vestiges et transmission. Ses formes semblent parfois provenir d''une civilisation réelle ou imaginaire et interrogent ce que nous conservons, reconstruisons ou projetons sur nos héritages.', 'A visual artist working in particular with sculpture and ceramics, Nathalie Morere develops a universe where memory, identity, vestiges and transmission meet. Her forms sometimes seem to come from a real or imaginary civilisation and question what we preserve, rebuild or project onto our heritage.', '/images/artworks/morere-2.jpg', 'https://g3a.org/g3a-visual-arts-2026-decouvrez-les-six-artistes-selectionnes/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('kenof', 'KeNoF', 'Peinture, sculpture, installation et performance', 'Painting, sculpture, installation and performance', 'Artiste multidisciplinaire d''origine camerounaise, KeNoF travaille entre peinture, sculpture, installation et performance. Son univers met en relation mémoire, spiritualité, déplacement et héritage bamiléké, en transformant les références traditionnelles en matériaux de création contemporaine.', 'A multidisciplinary artist of Cameroonian origin, KeNoF works across painting, sculpture, installation and performance. His universe connects memory, spirituality, displacement and Bamileke heritage, turning traditional references into materials for contemporary creation.', '/images/artworks/kenof-1.jpg', 'https://g3a.org/g3a-visual-arts-2026-decouvrez-les-six-artistes-selectionnes/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
INSERT INTO "Creator" ("slug", "name", "specialty", "specialtyEn", "bio", "bioEn", "image", "sourceUrl") VALUES ('paula-padua-nogueira', 'Paula Padua Nogueira', 'Peinture', 'Painting', 'À travers la peinture, Paula Padua Nogueira explore une identité traversée par plusieurs héritages, notamment congolais, portugais et belge. Son travail aborde le métissage, le colorisme, les standards de beauté, la mémoire coloniale et la manière dont le regard social participe à la construction de l''identité.', 'Through painting, Paula Padua Nogueira explores an identity shaped by several heritages, notably Congolese, Portuguese and Belgian. Her work addresses mixed heritage, colourism, beauty standards, colonial memory and the way the social gaze contributes to the construction of identity.', '/images/artworks/padua-2.jpg', 'https://g3a.org/g3a-visual-arts-2026-decouvrez-les-six-artistes-selectionnes/')
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "specialty" = EXCLUDED."specialty", "specialtyEn" = EXCLUDED."specialtyEn", "bio" = EXCLUDED."bio", "bioEn" = EXCLUDED."bioEn", "image" = EXCLUDED."image", "sourceUrl" = EXCLUDED."sourceUrl";
