INSERT INTO "Product" ("slug", "name", "nameEn", "description", "descriptionEn", "story", "storyEn", "categorySlug", "creatorSlug", "priceCents", "materials", "sizes", "dimensions", "stock", "images", "createdAt") VALUES ('trois-reliefs-ceramique-blanche', 'Trois reliefs muraux en céramique blanche', 'Three white ceramic wall reliefs', 'Trio de pièces murales en céramique blanche, ornées de motifs floraux, de figures animales et de franges modelées.', 'Trio of white ceramic wall pieces, decorated with floral motifs, animal figures and modelled fringes.', 'Ces formes semblent provenir d''une civilisation réelle ou imaginaire (Nathalie Morere, G3A Visual Arts 2026).', 'These forms seem to come from a real or imaginary civilisation (Nathalie Morere, G3A Visual Arts 2026).', 'sculpture-ceramique', 'nathalie-morere', 140000, '[{"fr":"Céramique","en":"Ceramics"}]'::jsonb, '[]'::jsonb, NULL, 1, '["/images/artworks/morere-1.jpg"]'::jsonb, '2026-09-26T00:00:00.000Z'::timestamp)
