INSERT INTO "Product" ("slug", "name", "nameEn", "description", "descriptionEn", "story", "storyEn", "categorySlug", "creatorSlug", "priceCents", "materials", "sizes", "dimensions", "stock", "images", "createdAt") VALUES ('sculpture-ceramique-vasque-bleue', 'Sculpture céramique à la vasque bleue', 'Ceramic sculpture with a blue basin', 'Pièce verticale en céramique : un visage en relief orne une vasque émaillée bleue, posée sur un corps à ailes plumées.', 'Vertical ceramic piece: a relief face adorns a blue glazed basin set on a body with feathered wings.', 'Entre mémoire et transmission, une pièce qui interroge ce que nous conservons ou reconstruisons de nos héritages.', 'Between memory and transmission, a piece that questions what we preserve or rebuild from our heritage.', 'sculpture-ceramique', 'nathalie-morere', 95000, '[{"fr":"Céramique","en":"Ceramics"}]'::jsonb, '[]'::jsonb, NULL, 1, '["/images/artworks/morere-2.jpg"]'::jsonb, '2026-09-25T00:00:00.000Z'::timestamp)
