INSERT INTO "Product" ("slug", "name", "nameEn", "description", "descriptionEn", "story", "storyEn", "categorySlug", "creatorSlug", "priceCents", "materials", "sizes", "dimensions", "stock", "images", "createdAt") VALUES ('kenof-figure-voilee-et-coiffe', 'Figure voilée et haute coiffe', 'Veiled figure and tall headdress', 'Une figure drapée de bleu et un personnage à la haute coiffe sculptée, devant une foule dessinée à l''encre, sur des fonds violets.', 'A figure draped in blue and a character with a tall sculpted headdress, in front of an ink-drawn crowd, on violet grounds.', 'Une œuvre qui met en relation mémoire, spiritualité et héritage bamiléké (KeNoF, G3A Visual Arts 2026).', 'A work that connects memory, spirituality and Bamileke heritage (KeNoF, G3A Visual Arts 2026).', 'peinture', 'kenof', 580000, '[{"fr":"Peinture","en":"Painting"}]'::jsonb, '[]'::jsonb, NULL, 1, '["/images/artworks/kenof-1.jpg"]'::jsonb, '2026-09-24T00:00:00.000Z'::timestamp)
